import { useQuery } from '@tanstack/react-query';
import { lineItemsKey, fetchLineItems, type LineItem } from './queries';
import { fetchInvoiceDiscount, invoiceDiscountKey } from '../invoices/queries';
import { LineItemRow } from '../../slots/defs/lineItemRow';
import { formatMoney } from '../../ui/money';

// An invoice's line items plus the derived total. Queries for itself under ['lineitems', invoiceId]
// — never handed its data by a parent (CLAUDE.md rule 5). Each line's amount is qty * unitPrice; the
// invoice total is the sum of the same rows LESS the invoice's percentage discount, worked out
// server-side under the shared ['lineitems', invoiceId] key so it always tracks both the lines and
// the discount. With no discount the total equals the plain line sum. Carries the stable
// data-testid contract the test reads.
export function LineItemsTable({ invoiceId }: { invoiceId: number }) {
  const { data: lineItems } = useQuery({
    queryKey: lineItemsKey(invoiceId),
    queryFn: () => fetchLineItems(invoiceId),
  });
  const { data: discount } = useQuery({
    queryKey: invoiceDiscountKey(invoiceId),
    queryFn: () => fetchInvoiceDiscount(invoiceId),
  });

  if (!lineItems) {
    return null;
  }

  const subtotal = lineItems.reduce(
    (sum, line) => sum + Number(line.qty) * Number(line.unitPrice),
    0,
  );
  const total = discount ? Number(discount.total) : subtotal;

  return (
    <>
      <table data-testid="invoice-lineitems-table">
        <thead>
          <tr>
            <th>Description</th>
            <th>Qty</th>
            <th>Unit</th>
            <th>Unit price</th>
            <th>Amount</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {lineItems.map((line: LineItem) => (
            <tr key={line.id} data-testid={`lineitem-row-${line.id}`}>
              <td data-testid="lineitem-description">{line.description}</td>
              <td data-testid="lineitem-qty">{line.qty}</td>
              <td data-testid="lineitem-unit">{line.unit}</td>
              <td data-testid="lineitem-unitprice">{formatMoney(line.unitPrice)}</td>
              <td data-testid="lineitem-amount">
                {formatMoney(Number(line.qty) * Number(line.unitPrice))}
              </td>
              <LineItemRow.Slot
                invoiceId={invoiceId}
                lineItemId={line.id}
                description={line.description}
                qty={Number(line.qty)}
                unitPrice={Number(line.unitPrice)}
              />
            </tr>
          ))}
        </tbody>
      </table>
      <p data-testid="invoice-amount">{formatMoney(total)}</p>
    </>
  );
}
=== lineitems queries ===
import { getJson, postJson } from '../../api/http';

// An invoice's line items under a per-invoice key: anything showing invoice 1's lines reads
// ['lineitems', 1], and a write invalidates the same key to refresh them (CLAUDE.md rule 5). A line
// carries what is being charged for (description), how many (qty), the unit that quantity is measured
// in (unit, e.g. "hours") and the price each (unitPrice).
export type LineItem = {
  id: number;
  invoiceId: number;
  description: string;
  qty: number;
  unit: string;
  unitPrice: number;
};

export const lineItemsKey = (invoiceId: number) => ['lineitems', invoiceId] as const;

export function fetchLineItems(invoiceId: number): Promise<LineItem[]> {
  return getJson<LineItem[]>(`/api/invoices/${invoiceId}/lineitems`);
}

/** Add a line to an invoice; the invoice id is in the path, the rest is the body (CLAUDE.md server). */
export function createLineItem(
  invoiceId: number,
  input: { description: string; qty: number; unit: string; unitPrice: number },
): Promise<LineItem> {
  return postJson<LineItem>(`/api/invoices/${invoiceId}/lineitems`, input);
}

/** Change a line on an invoice; ids are in the path, the new values are the body. */
export function updateLineItem(
  invoiceId: number,
  lineItemId: number,
  input: { description: string; qty: number; unitPrice: number },
): Promise<LineItem> {
  return postJson<LineItem>(`/api/invoices/${invoiceId}/lineitems/${lineItemId}`, input);
}

/** Remove a line from an invoice; both ids are in the path, no body needed. */
export function removeLineItem(invoiceId: number, lineItemId: number): Promise<void> {
  return postJson<void>(`/api/invoices/${invoiceId}/lineitems/${lineItemId}/remove`, {});
}

