        this.projectId = invoice.getProjectId();
        this.amount = invoice.getAmount();
        this.status = deriveStatus(invoice.getStatus(), invoice.getAmount(), paid);
        this.issuedDate = invoice.getIssuedDate();
        this.dueDate = invoice.getDueDate();
        this.paid = paid;
