        BigDecimal pd = paid == null ? BigDecimal.ZERO : paid;
        if (amt.signum() > 0 && pd.compareTo(amt) >= 0) {
            return "PAID";
        }
        if (pd.signum() > 0) {
            return "PARTIAL";
        }
        return stored;
    }

